UPDATE im_conversation
SET unread_count = unread_count + #{count}
WHERE conversation_id = #{conversationId}

UPDATE im_conversation
SET unread_count = 0
WHERE conversation_id = #{conversationId}

UPDATE im_conversation
SET last_msg_id      = #{lastMsgId},
    last_msg_content = #{lastMsgContent},
    last_msg_time    = #{lastMsgTime}
WHERE conversation_id = #{conversationId}
